// Página original recebida pelo workflow
const page = $('Receber Página e Configuração').first().json.Page;

// Propriedades enriquecidas
const resolvedProperties =
  $('Preparar Propriedades Enriquecidas').first().json.resolvedProperties ?? [];

const resolved = {};

for (const property of resolvedProperties) {
  Object.assign(resolved, property);
}

// Conteúdo da página
const content =
  $('Preparar Conteúdo da Página').first().json.content ?? [];

// Retorna a página original + propriedades enriquecidas + conteúdo
return [
  {
    json: {
      ...page,
      ...resolved,
      content,
    },
  },
];
